from __future__ import annotations

def affine_history(a: float, b: float, x0: float, steps: int) -> list[float]:
    if abs(a) >= 1.0:
        raise ValueError("abs(a) must be below one")
    history = [x0]
    for _ in range(steps):
        history.append(a * history[-1] + b)
    return history

if __name__ == "__main__":
    fixed = 3.0 / (1.0 - 0.5)
    for start in (0.0, 20.0):
        values = affine_history(0.5, 3.0, start, 12)
        print(start, values, "final error", abs(values[-1] - fixed))

from __future__ import annotations

def show_paradoxes() -> None:
    discriminant = (-1.0)**2 - 4.0
    print("x^2 + 1 = x discriminant:", discriminant)
    negate = {False: True, True: False}
    fixed = [b for b in negate if negate[b] == b]
    print("Boolean-negation fixed points:", fixed)
    print("orbit from False:", False, negate[False], negate[negate[False]])

if __name__ == "__main__":
    show_paradoxes()

