from __future__ import annotations
import matplotlib.pyplot as plt

def main() -> None:
    f = lambda x: 0.5*x + 3.0
    fixed = 6.0
    for start, color in [(0.0, "#2563eb"), (20.0, "#dc2626")]:
        xs = [start]
        for _ in range(14): xs.append(f(xs[-1]))
        plt.semilogy(range(len(xs)), [max(abs(x-fixed), 1e-12) for x in xs], "o-", color=color, label=f"x0={start:g}")
    plt.xlabel("Circuit number"); plt.ylabel("Distance to consistent state")
    plt.title("Geometric attraction to x*=6"); plt.grid(True, which="both", alpha=.3); plt.legend(); plt.tight_layout(); plt.show()
if __name__ == "__main__": main()

